async function lookupCep(f){const cep=f.elements.cep.value.replace(/\D/g,'');if(cep.length!==8){setAddressStatus('Informe um CEP de 8 dígitos.','warning');return}addressLookup?.abort();const ctrl=new AbortController();addressLookup=ctrl;const timeout=setTimeout(()=>ctrl.abort(),7000);setAddressStatus('Consultando cidade e UF…','loading');$('lookupCep').disabled=true;try{const resp=await fetch('https://viacep.com.br/ws/'+cep+'/json/',{signal:ctrl.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!resp.ok)throw Error();const data=await resp.json();if(addressLookup!==ctrl||!f.isConnected||f.elements.cep.value.replace(/\D/g,'')!==cep)return;if(data.erro){setAddressStatus('CEP não localizado. Confira os dígitos.','warning');return}orderAddress.city=String(data.localidade||'');orderAddress.uf=String(data.uf||'');setAddressStatus([orderAddress.city,orderAddress.uf].filter(Boolean).join(' — ')||'CEP localizado.','success')}catch{if(addressLookup===ctrl&&f.isConnected)setAddressStatus('Consulta indisponível. Você ainda pode enviar seu CEP à loja.','warning')}finally{clearTimeout(timeout);if(addressLookup===ctrl){addressLookup=null;if(f.isConnected)$('lookupCep').disabled=false}}}
