let favorites=new Set(),toastTimer;try{const f=JSON.parse(localStorage.getItem('apell.favorites.v1')||'[]');if(Array.isArray(f))favorites=new Set(f.filter(k=>typeof k==='string'&&/^\d+:\d+$/.test(k)&&products[+k.split(':')[0]]?.colors[+k.split(':')[1]]))}catch{}
function subtotal(){return bag.reduce((s,x)=>s+(itemProduct(x).price||0)*x.qty,0)}
function toast(message){const t=$('motionToast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,2600)}
function syncFavorites(){document.querySelectorAll('[data-fav]').forEach(b=>{const on=favorites.has(b.dataset.fav);b.setAttribute('aria-pressed',String(on));b.setAttribute('title',on?'Remover dos favoritos':'Salvar nos favoritos')});$('favCount').hidden=!favorites.size;$('favCount').textContent=favorites.size;$('favoriteBtn').setAttribute('aria-label',`Favoritos, ${favorites.size} peças`);try{localStorage.setItem('apell.favorites.v1',JSON.stringify([...favorites]))}catch{}}
function toggleFav(k){const on=favorites.has(k);on?favorites.delete(k):favorites.add(k);syncFavorites();toast(on?'Peça removida dos favoritos.':'Peça guardada nos favoritos.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-fav]');if(!b)return;toggleFav(b.dataset.fav);if(b.closest('.favorites-list'))showFavorites()});
const observer=new MutationObserver(syncFavorites);observer.observe($('products'),{childList:true});syncFavorites();
function showFavorites(){openPanel('Seus favoritos',favorites.size?`<div class="favorites-list">${[...favorites].map(k=>{const [p,c]=k.split(':').map(Number),pr=products[p],co=pr.colors[c];return `<div class="fav-row"><button class="search-result" data-open-product="${k}"><img src="${image(co)}" alt=""><span>${pr.title}<small>${co[0]} · ${money(pr.price)}</small></span>${icon('arrow')}</button><button class="icon-button" data-fav="${k}" aria-label="Remover ${co[0]} dos favoritos">${icon('heart')}</button></div>`}).join('')}</div>`:`<div class="empty">${icon('heart')}<h3>Seus favoritos</h3><p class="note">Toque no coração de uma peça para encontrá-la aqui.</p><button class="primary wide" id="browseFav">Explorar coleção ${icon('arrow')}</button></div>`);syncFavorites();body.querySelectorAll('[data-open-product]').forEach(b=>b.onclick=()=>showProduct(...b.dataset.openProduct.split(':').map(Number)));if($('browseFav'))$('browseFav').onclick=()=>{panel.close();goCollection()}}
$('favoriteBtn').onclick=showFavorites;
