function slug(s){return clean(s).replaceAll(' ','-')}
const entryUrl=(route,color)=>new URL('/p/'+route+'/'+slug(color)+'.html',location.origin).href;
function setProductMeta(title,color,description,src){document.title=title+' — '+color+' | APELL';document.querySelector('meta[name="description"]').content=title+' em '+color+'. '+description;document.querySelector('meta[property="og:title"]').content=document.title;document.querySelector('meta[property="og:description"]').content=document.querySelector('meta[name="description"]').content;document.querySelector('meta[property="og:image"]').content=new URL(src,location.origin+'/').href;}
